<?php
declare(strict_types=1); require_once __DIR__ . '/../config/db.php'; require_once __DIR__ . '/../includes/layout.php'; requireAdmin();
if ($_SERVER['REQUEST_METHOD']==='POST') { verifyCsrf($_POST['csrf_token']??null); $action=$_POST['action']??''; $id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT); if($action==='delete' && $id){$stmt=$pdo->prepare('DELETE FROM rooms WHERE id=:id AND NOT EXISTS (SELECT 1 FROM leases WHERE room_id=:id AND status=\'active\')');$stmt->execute([':id'=>$id]);redirectWith('rooms.php','success','Room deleted if it had no active lease.');} $number=trim((string)($_POST['room_number']??''));$floor=filter_input(INPUT_POST,'floor',FILTER_VALIDATE_INT);$capacity=filter_input(INPUT_POST,'capacity',FILTER_VALIDATE_INT);$beds=filter_input(INPUT_POST,'occupied_beds',FILTER_VALIDATE_INT);$rate=(float)($_POST['monthly_rate']??0);$status=$_POST['status']??'available';if($number===''||$floor===false||$capacity===false||$beds===false||$capacity<1||$beds<0||$beds>$capacity||$rate<0||!in_array($status,['available','full','maintenance'],true))redirectWith('rooms.php','error','Enter valid room details.');if($action==='update'&&$id){$stmt=$pdo->prepare('UPDATE rooms SET room_number=:number,floor=:floor,capacity=:capacity,occupied_beds=:beds,monthly_rate=:rate,status=:status WHERE id=:id');$stmt->execute([':number'=>$number,':floor'=>$floor,':capacity'=>$capacity,':beds'=>$beds,':rate'=>$rate,':status'=>$status,':id'=>$id]);}else{$stmt=$pdo->prepare('INSERT INTO rooms (room_number,floor,capacity,occupied_beds,monthly_rate,status) VALUES (:number,:floor,:capacity,:beds,:rate,:status)');$stmt->execute([':number'=>$number,':floor'=>$floor,':capacity'=>$capacity,':beds'=>$beds,':rate'=>$rate,':status'=>$status]);}redirectWith('rooms.php','success','Room saved.');}
$rooms=$pdo->query('SELECT * FROM rooms ORDER BY floor,room_number')->fetchAll();pageHeader('Rooms');?><div class="grid gap-6 lg:grid-cols-3"><section class="rounded-lg border border-slate-200 bg-white p-6 shadow-sm"><h1 class="text-xl font-bold">Add room</h1><form class="mt-4 space-y-3" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input class="w-full rounded border p-2" name="room_number" placeholder="Room number" required><input class="w-full rounded border p-2" type="number" name="floor" placeholder="Floor" required><input class="w-full rounded border p-2" type="number" min="1" name="capacity" placeholder="Capacity" required><input class="w-full rounded border p-2" type="number" min="0" name="occupied_beds" placeholder="Occupied beds" required><input class="w-full rounded border p-2" type="number" step="0.01" min="0" name="monthly_rate" placeholder="Monthly rate" required><select class="w-full rounded border p-2" name="status"><option>available</option><option>full</option><option>maintenance</option></select><button class="rounded bg-teal-700 px-4 py-2 font-semibold text-white">Add room</button></form></section><section class="rounded-lg border border-slate-200 bg-white p-6 shadow-sm lg:col-span-2"><h2 class="text-xl font-bold">Room directory</h2><div class="mt-4 space-y-4"><?php foreach($rooms as $room):?><form class="grid gap-2 border-b pb-4 md:grid-cols-6" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="id" value="<?=e((string)$room['id'])?>"><input class="rounded border p-2" name="room_number" value="<?=e($room['room_number'])?>"><input class="rounded border p-2" type="number" name="floor" value="<?=e((string)$room['floor'])?>"><input class="rounded border p-2" type="number" name="capacity" value="<?=e((string)$room['capacity'])?>"><input class="rounded border p-2" type="number" name="occupied_beds" value="<?=e((string)$room['occupied_beds'])?>"><input class="rounded border p-2" type="number" step="0.01" name="monthly_rate" value="<?=e((string)$room['monthly_rate'])?>"><div class="flex gap-2"><select class="min-w-0 rounded border p-2" name="status"><option <?= $room['status']==='available'?'selected':'' ?>>available</option><option <?= $room['status']==='full'?'selected':'' ?>>full</option><option <?= $room['status']==='maintenance'?'selected':'' ?>>maintenance</option></select><button class="rounded bg-slate-900 px-3 text-white" name="action" value="update">Save</button><button class="rounded bg-rose-700 px-3 text-white" name="action" value="delete">Delete</button></div></form><?php endforeach;?></div></section></div><?php pageFooter();?>